<?php
require __DIR__.'/../includes/bootstrap.php';require_permission('banners');$msg='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$image='';if(!empty($_FILES['image']['name']))$image=upload_store_image('image');if(!$image)throw new RuntimeException('اختر صورة البانر من الهاتف.');db()->prepare('INSERT INTO banners(title,subtitle,image_url,link_url,sort_order,is_active) VALUES(?,?,?,?,?,?)')->execute([trim($_POST['title']),trim($_POST['subtitle']),$image,trim($_POST['link_url']),(int)$_POST['sort_order'],isset($_POST['is_active'])?1:0]);$msg='تمت إضافة البانر.';}catch(Throwable $e){$error=$e->getMessage();}}$items=db()->query('SELECT * FROM banners ORDER BY sort_order,id')->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>البانرات</title><link rel="stylesheet" href="../assets/css/store.css"></head><body><main class="inner"><a href="index.php">← لوحة التحكم</a><h1>إدارة البانرات</h1><?php if($msg):?><p class="notice"><?=h($msg)?></p><?php endif?><?php if($error):?><p class="notice"><?=h($error)?></p><?php endif?><form method="post" enctype="multipart/form-data" class="admin-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>العنوان<input name="title" required></label><label>الوصف<input name="subtitle"></label><label>صورة البانر من الهاتف<input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif" required></label><label>رابط الانتقال<input name="link_url"></label><label>الترتيب<input type="number" name="sort_order" value="0"></label><label><input type="checkbox" name="is_active" checked> منشور</label><button class="gold">إضافة بانر</button></form><div class="table-wrap"><table><tr><th>العنوان</th><th>الصورة</th><th>الحالة</th></tr><?php foreach($items as $b):?><tr><td><?=h($b['title'])?></td><td><img width="90" src="../<?=h($b['image_url'])?>" alt=""></td><td><?=$b['is_active']?'منشور':'مخفي'?></td></tr><?php endforeach?></table></div></main></body></html>